head.script:
scwin.init = function() {
    var jsonData = [{
            "category1": "1",
            "category2": "shin"
        },
        {
            "category1": "2",
            "category2": "shin"
        },
        {
            "category1": "0",
            "category2": "kim"
        },
        {
            "category1": "2",
            "category2": "kim"
        },
        {
            "category1": "1",
            "category2": "kim"
        },
        {
            "category1": "0",
            "category2": "kim"
        },
        {
            "category1": "2",
            "category2": "kim"
        },
        {
            "category1": "1",
            "category2": "shin"
        }
    ];
    dataList1.setJSON(jsonData);
};
scwin.grid1_ongroupby = function(options) {
    return false;
};
scwin.unitTest = function() {
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('triger6').click()");
    WebSquare.wUnit.addCommand("assert", "ischeckbox", "false");
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
};
scwin.triger6_onclick = function(e) {
    // category1 header filter click
    var filter = WebSquare.wUnit.getDomById($p.id + 'grid1_header_category1_filter');
    filter.click();
    // filterList 전체선택 check하여 해지
    var checkbox = WebSquare.wUnit.getDomById($p.id + 'grid1_customFilter_list').childNodes[1].childNodes[0];
    checkbox.click();
    // category2 header filter click	
    var filter1 = WebSquare.wUnit.getDomById($p.id + 'grid1_header_category2_filter');
    filter1.click();
    // filterList 전체선택 체크값 확인	
    var checkbox1 = WebSquare.wUnit.getDomById($p.id + 'grid1_customFilter_list').childNodes[1].childNodes[0];
    // 	category2의 filterList 전체선택 체크값이 해지되면정상이고 값비교		
    ischeckbox = checkbox1.checked;
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    // 자동화수행
    // category2 filterList의 전체선택 체크박스 체크해지(true)비교을 위한 변수선언
    window.ischeckbox = true;
    // 자동화테스트를 위한 버튼생성
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
